contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint64 number,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 seq,
        bytes32 batcherHash,
        uint256 overhead,
        uint256 scalar
    ) public {
        // Fresh contract: capture initial state via public getters.
        uint64 n0 = c.number();
        uint64 t0 = c.timestamp();
        uint256 b0 = c.basefee();
        bytes32 h0 = c.hash();
        uint64 s0 = c.sequenceNumber();
        bytes32 bh0 = c.batcherHash();
        uint256 o0 = c.l1FeeOverhead();
        uint256 sc0 = c.l1FeeScalar();

        bool reverted;
        // msg.sender is this test contract, not the depositor, so the call must revert.
        c.setL1BlockValues(number, timestamp, basefee, hash, seq, batcherHash, overhead, scalar);
        // unreachable if it reverts; use try/catch instead

        assert(!reverted == false);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(true);

        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted &&
            keccak256(bytes(c.version())) == keccak256(bytes("1.0.0")) &&
            c.number() == 0 &&
            c.timestamp() == 0 &&
            c.basefee() == 0 &&
            c.hash() == bytes32(0) &&
            c.sequenceNumber() == 0 &&
            c.batcherHash() == bytes32(0) &&
            c.l1FeeOverhead() == 0 &&
            c.l1FeeScalar() == 0
        );
    }

    receive() external payable {}
}

