contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        address depositor = c.DEPOSITOR_ACCOUNT();
        require(depositor != address(this));

        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // c must still be fully callable after the revert
        uint64 numAfter = c.number();
        uint256 feeAfter = c.l1FeeScalar();

        assert(reverted && depositor != address(this) && numAfter == 0 && feeAfter == 0);
    }
    receive() external payable {}
}

