        uint64 tsBefore = c.timestamp();

        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint64 numAfter = c.number();
        uint64 tsAfter = c.timestamp();

        assert(reverted && numBefore == 0 && tsBefore == 0 && numAfter == numBefore && tsAfter == tsBefore && numAfter == tsAfter);
    }
    receive() external payable {}
}

